import firebase_admin
from firebase_admin import auth

def email_password_login(email, password):
    if not firebase_admin._apps:
        firebase_admin.initialize_app()
    user = auth.get_user_by_email(email)
    try:
        user = auth.verify_password(password, user.uid)
        return user.uid
    except firebase_admin.auth.UserNotFoundError:
        raise RuntimeError('User not found')
    except firebase_admin.auth.InvalidEmailError:
        raise RuntimeError('Invalid email')
    except firebase_admin.auth.InvalidPasswordError:
        raise RuntimeError('Invalid password')

import firebase_admin
from firebase_admin import auth

def refresh_session(refresh_token):
    if not firebase_admin._apps:
        firebase_admin.initialize_app()
    try:
        new_token = auth.refresh_id_token(refresh_token)
        return new_token
    except firebase_admin.auth.AuthError as e:
        raise RuntimeError('Failed to refresh session: ' + str(e))

import firebase_admin
from firebase_admin import auth

def password_reset(email):
    if not firebase_admin._apps:
        firebase_admin.initialize_app()
    try:
        auth.generate_password_reset_link(email)
        return 'Password reset link sent to ' + email
    except firebase_admin.auth.UserNotFoundError:
        raise RuntimeError('User not found')

import os
import firebase_admin
from firebase_admin import credentials

def initialize_firebase_app():
    if not firebase_admin._apps:
        cred = credentials.Certificate({
            'type': os.getenv('FIREBASE_TYPE'),
            'project_id': os.getenv('FIREBASE_PROJECT_ID'),
            'private_key_id': os.getenv('FIREBASE_PRIVATE_KEY_ID'),
            'private_key': os.getenv('FIREBASE_PRIVATE_KEY'),
            'client_email': os.getenv('FIREBASE_CLIENT_EMAIL'),
            'client_id': os.getenv('FIREBASE_CLIENT_ID'),
            'auth_uri': os.getenv('FIREBASE_AUTH_URI'),
            'token_uri': os.getenv('FIREBASE_TOKEN_URI'),
            'auth_provider_x509_cert_url': os.getenv('FIREBASE_AUTH_PROVIDER_X509_CERT_URL'),
            'client_x509_cert_url': os.getenv('FIREBASE_CLIENT_X509_CERT_URL')
        })
        firebase_admin.initialize_app(cred)

def get_firebase_app():
    return firebase_admin.get_app()

from typing import Any, Dict

def normalize_register_payload(payload: Dict[str, Any]) -> Dict[str, Any]:
    return {
        'email': payload['email'],
        'password': payload['password']
    }

def normalize_login_payload(payload: Dict[str, Any]) -> Dict[str, Any]:
    return {
        'email': payload['email'],
        'password': payload['password']
    }

def normalize_refresh_payload(payload: Dict[str, Any]) -> Dict[str, Any]:
    return {
        'refresh_token': payload['refresh_token']
    }

def normalize_password_reset_payload(payload: Dict[str, Any]) -> Dict[str, Any]:
    return {
        'email': payload['email']
    }

import boto3

def summarize_text(text):
    textract = boto3.client('textract')
    response = textract.analyze_document(Document={'Bytes': text.encode('utf-8')}, FeatureTypes=['TABLES', 'FORMS'])
    blocks = response['Blocks']
    summary = ''
    for block in blocks:
        if block['BlockType'] == 'LINE':
            summary += block['Text'] + ' '
    return summary
